import { cx, useRef, useControllable } from '../react.js';
import { BuiltinIcon } from '../builtin-icons.jsx';
import { IconButton } from './Button.jsx';
import { Badge } from './Badge.jsx';
import { describe } from '../doc.js';
import { useFloating, themeAttrs, useAppear, useReady } from '../theme-flags.js';
import { useHighlight } from '../highlight.js';

/** The bar at the top of a mobile screen: back, title, up to two actions. */
export function Navbar({ title, subtitle, showBack = true, titleVisible = true, onBack, backLabel = 'Back', actions = [], floating, glass, className, ...rest }) {
  const isFloating = useFloating(floating);
  return (
    <header data-slot="navbar" className={cx('bui-navbar', isFloating && 'bui-navbar--floating', className)} {...themeAttrs({ glass })} {...rest}>
      <div data-slot="navbar-side" className="bui-navbar__side">
        {showBack && <IconButton variant="ghost" size="md" className="bui-navbar__back" label={backLabel} tooltip={false} icon={<BuiltinIcon name="arrowLeft" size={24} />} onClick={onBack} />}
      </div>
      <div data-slot="navbar-heading" className="bui-navbar__heading">
        <h1 data-slot="navbar-title" className="bui-navbar__title" data-hidden={titleVisible ? undefined : ''} aria-hidden={titleVisible ? undefined : true}>
          {title}
        </h1>
        {subtitle && (
          <div data-slot="navbar-subtitle" className="bui-navbar__subtitle">
            {subtitle}
          </div>
        )}
      </div>
      <div data-slot="navbar-side" className={cx('bui-navbar__side', 'bui-navbar__side--end')}>
        {actions.slice(0, 2).map((a) => (
          <IconButton key={a.label} variant="ghost" size="md" label={a.label} tooltip={false} icon={a.icon} onClick={a.onClick} disabled={a.disabled} />
        ))}
      </div>
    </header>
  );
}
describe(Navbar, 'The bar at the top of a mobile screen: a back button on the left, the title in the middle and up to two icon actions on the right', {
  title: ['string', null, 'Screen title, centered; a long one is truncated'],
  subtitle: ['string', null, 'A second line under the title'],
  showBack: ['boolean', 'true', 'Show the back button'],
  titleVisible: ['boolean', 'true', 'false hides the title (it fades) until the screen has its own heading scrolled out of view; the bar keeps its place'],
  onBack: ['() => void', null, 'Called when the back button is pressed'],
  backLabel: ['string', "'Back'", 'Accessible name of the back button'],
  floating: [
    'boolean',
    'theme',
    'A floating bar: separate rounded pieces with a shadow over a gradient that fades the content (blurred when glass is on), inset from the screen edges; by default it follows the Floating setting of the theme',
  ],
  glass: ['boolean', 'theme', 'Translucent, blurred bar; true or false overrides the Glass setting of the theme'],
  actions: [
    'Array<{ icon: ReactNode; label: string; onClick?: () => void; disabled?: boolean }>',
    '[]',
    'Icon buttons on the right; only the first two are shown. `label` is the accessible name',
  ],
});

/** The tab bar at the bottom of a mobile screen: 2 to 6 top-level destinations. */
export function BottomBar({
  items = [],
  value,
  defaultValue,
  onValueChange,
  showLabels = true,
  floating,
  glass,
  motion,
  label = 'Main navigation',
  className,
  ...rest
}) {
  const [current, setCurrent] = useControllable(value, defaultValue ?? items[0]?.value, onValueChange);
  const isFloating = useFloating(floating);
  const ref = useRef(null);
  const pillRef = useRef(null);
  const barRef = useRef(null);
  const ready = useReady();
  // The highlight is one element that slides to the active item: the whole item when floating, its icon otherwise.
  const [pill] = useHighlight(
    barRef,
    (bar) => {
      const item = bar.querySelector('[aria-current="page"]');
      return item && (isFloating ? item : item.querySelector('.bui-bottombar__icon'));
    },
    [current, items.length, showLabels, isFloating],
  );
  useAppear(pillRef, ref, pill && `${pill.x}/${pill.y}`);
  return (
    <nav
      ref={ref}
      aria-label={label}
      data-slot="bottombar"
      className={cx(
        'bui-bottombar',
        ready && 'bui-bottombar--ready',
        !showLabels && 'bui-bottombar--compact',
        isFloating && 'bui-bottombar--floating',
        className,
      )}
      {...themeAttrs({ motion, glass })}
      {...rest}
    >
      <div ref={barRef} data-slot="bottombar-bar" className="bui-bottombar__bar">
        {pill && (
          <span
            ref={pillRef}
            data-slot="bottombar-pill"
            className="bui-bottombar__pill"
            aria-hidden="true"
            style={{ width: pill.w, height: pill.h, transform: `translate(${pill.x}px, ${pill.y}px)` }}
          />
        )}
        {items.slice(0, 6).map((it) => {
          const active = it.value === current;
          const badge =
            it.badge === true ? (
              <Badge type="dot" variant="red" size="lg" label="New" className="bui-bottombar__badge" />
            ) : (
              it.badge != null && <Badge type="counter" variant="red" size="sm" label={it.badge} className="bui-bottombar__badge" />
            );
          return (
            <button
              key={it.value}
              type="button"
              data-slot="bottombar-item"
              className={cx('bui-bottombar__item', active && 'bui-bottombar__item--active')}
              aria-current={active ? 'page' : undefined}
              aria-label={showLabels ? undefined : it.label}
              disabled={it.disabled}
              onClick={() => setCurrent(it.value)}
            >
              <span data-slot="bottombar-icon" className="bui-bottombar__icon" aria-hidden="true">
                {active && it.activeIcon ? it.activeIcon : it.icon}
                {badge || null}
              </span>
              {showLabels && (
                <span data-slot="bottombar-label" className="bui-bottombar__label">
                  {it.label}
                </span>
              )}
            </button>
          );
        })}
      </div>
    </nav>
  );
}
describe(
  BottomBar,
  'The bar at the bottom of a mobile screen for switching between 2 to 6 top-level sections. The active one is highlighted; it can also float above the content, like the tab bar in iOS',
  {
    items: [
      'Array<{ value: string; label: string; icon: ReactNode; activeIcon?: ReactNode; badge?: number | string | true; disabled?: boolean }>',
      null,
      'The destinations (2 to 6); only the first six are shown. `activeIcon` (for example a filled icon) replaces `icon` when selected; `badge: true` shows a dot and a number shows a counter',
    ],
    value: ['string', null, 'Active destination (controlled)'],
    defaultValue: ['string', null, 'Initially active destination; the first by default'],
    onValueChange: ['(value: string) => void', null, 'Called when a destination is chosen'],
    showLabels: ['boolean', 'true', 'Show the labels under the icons; without them each label stays as the accessible name'],
    floating: [
      'boolean',
      'theme',
      'A floating bar: separate rounded pieces with a shadow over a gradient that fades the content (blurred when glass is on), inset from the screen edges; by default it follows the Floating setting of the theme',
    ],
    glass: ['boolean', 'theme', 'Translucent, blurred bar; true or false overrides the Glass setting of the theme'],
    motion: [
      "'off' | 'basic' | 'enhanced'",
      'theme',
      'Animations of this bar: off, basic, or enhanced (the highlight slides); by default the Animations setting of the theme',
    ],
    label: ['string', "'Main navigation'", 'Accessible name of the navigation'],
  },
);
